def sarif_schema_errors(report):
    """Return common built-in SARIF schema diagnostics in reference order."""
    errors=[]
    runs=report.get('runs',[]) if isinstance(report,dict) else []
    if not isinstance(runs,list): return errors
    lang_re=re.compile(r'^[a-zA-Z]{2}(-[a-zA-Z]{2})?$')
    for i,run in enumerate(runs):
        if not isinstance(run,dict): continue
        driver=run.get('tool',{}).get('driver',{}) if isinstance(run.get('tool'),dict) else {}
        if isinstance(driver,dict) and not lang_re.fullmatch(str(driver.get('language',''))):
            errors.append(f"runs.{i}.tool.driver.language: Does not match pattern '^[a-zA-Z]{{2}}(-[a-zA-Z]{{2}})?$'")
        if not lang_re.fullmatch(str(run.get('language',''))):
            errors.append(f"runs.{i}.language: Does not match pattern '^[a-zA-Z]{{2}}(-[a-zA-Z]{{2}})?$'")
        ns=run.get('newlineSequences')
        if not isinstance(ns,list) or not ns:
            errors.append(f'runs.{i}.newlineSequences: Array must have at least 1 items')
    return errors


def _hcl(text):
    """Catch common unterminated HCL expressions and delimiters."""
    stack=[]; quote=False; escape=False; line=1; col=0; i=0
    while i < len(text):
        c=text[i]; col+=1
        if c=='\n': line+=1; col=0
        if quote:
            if escape: escape=False
            elif c=='\\': escape=True
            elif c=='"': quote=False
            i+=1; continue
        if text.startswith('//',i) or c=='#':
            end=text.find('\n',i)
            if end<0: break
            i=end; continue
        if text.startswith('/*',i):
            end=text.find('*/',i+2)
            if end<0: return f'line {line}, column {col}: Unterminated block comment'
            segment=text[i:end+2]
            n=segment.count('\n')
            if n: line+=n; col=len(segment.rsplit('\n',1)[-1])
            else: col+=len(segment)-1
            i=end+2; continue
        if c=='"': quote=True
        elif c in '([{': stack.append((c,line,col))
        elif c in ')]}':
            if not stack: return f'line {line}, column {col}: Unmatched closing delimiter {c!r}'
            op,_,_=stack.pop()
            if (op,c) not in (('(',')'),('[',']'),('{','}')):
                return f'line {line}, column {col}: Mismatched closing delimiter {c!r}'
        i+=1
    if quote:
        return f'line {line}, column {col+1}: Invalid multi-line string: Quoted strings may not be split over multiple lines.'
    if stack or re.search(r'(?m)=\s*(?:#.*)?$', text):
        if text.endswith('\n'):
            eof_line, eof_col = line, 1
        else:
            eof_line, eof_col = line, col+1
        return f'line {eof_line}, column {eof_col}: Missing expression: Expected the start of an expression, but found the end of the file.'
    return None


